package com.bank.pitch.model;

// Holds the three blocks of a structured self-introduction plus the measurable result.
public class CandidateProfile {
    private final String present;   // who you are and what you do now
    private final String past;      // what you built, with a result
    private final String future;    // what you want to do next
    private final double resultBefore;
    private final double resultAfter;

    public CandidateProfile(String present, String past, String future,
                            double resultBefore, double resultAfter) {
        this.present = present;
        this.past = past;
        this.future = future;
        this.resultBefore = resultBefore;
        this.resultAfter = resultAfter;
    }

    public String getPresent() { return present; }
    public String getPast() { return past; }
    public String getFuture() { return future; }
    public double getResultBefore() { return resultBefore; }
    public double getResultAfter() { return resultAfter; }

    // A measurable achievement must move a number — this mirrors a real validation rule.
    public boolean hasMeasurableResult() {
        return resultBefore != resultAfter;
    }
}
